'use client';
import {useState,useEffect,useMemo,type FormEvent,type ReactNode} from 'react';
import {LayoutDashboard,Users,CalendarDays,BarChart3,Wallet,MessageCircle,Settings,Church,Plus,ArrowUpRight,ArrowDownLeft,ChevronLeft,ChevronRight,ChevronDown,Search,ArrowRight,Check,Clock,Heart,Link as LinkIcon,QrCode,Copy,Download,X,Menu,CheckCheck,MoreHorizontal,Mail,Phone,ShieldCheck,LogOut,ExternalLink,Send,CalendarCheck,UserPlus,RefreshCw,Archive,Pencil,Trash2,Printer,Info,CheckCircle2,AlertCircle,BookOpen,PlayCircle,Leaf} from 'lucide-react';
import QRCode from 'qrcode';
import {EquipeAcessos,Avaliacoes} from './equipe';
import {type Data,type Member,type Service,type Transaction,type Message,today,currency,sortMembers,eligible,statusFor,report,csvCell,moneyToCents,emptyData} from './domain';
import {API,presentesNoCulto,PAPEIS,type Me} from './domain';
const nav=[{id:'overview',label:'Visão geral',icon:LayoutDashboard},{id:'members',label:'Membros',icon:Users},{id:'attendance',label:'Cultos e presença',icon:CalendarDays},{id:'reports',label:'Relatórios',icon:BarChart3},{id:'finance',label:'Financeiro',icon:Wallet},{id:'messages',label:'Mensagens',icon:MessageCircle}];
const fmtDate=(v:string,opts:Intl.DateTimeFormatOptions={day:'2-digit',month:'short'})=>new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR',opts);
const monthLabel=(m:string)=>new Date(m+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
const initials=(s:string)=>s.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function Avatar({name,index=0}:{name:string;index?:number}){return <span className={'avatar av'+index%5}>{initials(name)}</span>}
function Button({children,onClick,variant='',disabled=false,type='button',className=''}:{children:ReactNode;onClick?:()=>void;variant?:string;disabled?:boolean;type?:'button'|'submit';className?:string}){return <button type={type} onClick={onClick} disabled={disabled} className={`btn ${variant} ${className}`}>{children}</button>}
function Pill({children,tone='green'}:{children:ReactNode;tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function Field({label,children,full=false}:{label:string;children:ReactNode;full?:boolean}){return <label className={'field '+(full?'full':'')}><span>{label}</span>{children}</label>}
function Empty({icon:Icon=Users,title,text,action}:{icon?:any;title:string;text:string;action?:ReactNode}){return <div className="empty"><span><Icon size={27}/></span><h3>{title}</h3><p>{text}</p>{action}</div>}
function downloadCSV(name:string,rows:unknown[][]){const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function getDemo():Data{const month=today().slice(0,7);const names=['Ana Paula Martins','André Luiz Costa','Beatriz Oliveira','Bruno Henrique Silva','Carla Regina Santos','Daniel Almeida','Débora Cristina Lima','Eduardo Ferreira','Elisa Moreira','Felipe Rodrigues','Gabriela Souza','Helena Ribeiro','Isabel Carvalho','João Pedro Gomes','Juliana Mendes','Lucas Oliveira','Marcos Vinícius','Maria Aparecida','Paulo Roberto','Raquel Dias','Renata Fernandes','Ricardo Alves','Sara Nascimento','Sérgio Azevedo'];const members=names.map((name,i)=>({id:'demo'+i,name,phone:'',email:'',birthDate:'',area:['Louvor','Recepção','Infantil',''][i%4],status:i>20?'visitor':'member',joinedDate:month+'-01',notes:'',source:i>20?'self':'manual',consent:0,archived:0,createdAt:new Date().toISOString()}));const services=[{id:'s1',title:'Culto da Família',date:month+'-01',time:'10:00',status:'closed',createdAt:''},{id:'s2',title:'Culto de Oração',date:month+'-04',time:'20:00',status:'closed',createdAt:''},{id:'s3',title:'Culto de Mulheres',date:month+'-05',time:'20:00',status:'closed',createdAt:''},{id:'s4',title:'Culto da Família',date:today(),time:'10:00',status:'open',createdAt:''}];return{...emptyData,members,services,attendance:services.filter(s=>s.status==='closed').flatMap((s,j)=>members.slice(0,21).filter((m,i)=>(i+j)%6!==0).map(m=>({serviceId:s.id,memberId:m.id,value:'present'}))),transactions:[{id:'t1',date:month+'-01',kind:'income',category:'Dízimos',description:'Dízimos · Culto da Família',amount:185000,memberId:'',paymentMethod:'Pix'},{id:'t2',date:month+'-04',kind:'income',category:'Ofertas',description:'Ofertas · Culto de Oração',amount:48700,memberId:'',paymentMethod:'Dinheiro'},{id:'t3',date:month+'-05',kind:'expense',category:'Manutenção',description:'Manutenção do espaço',amount:32000,memberId:'',paymentMethod:'Pix'},{id:'t4',date:month+'-06',kind:'income',category:'Dízimos',description:'Contribuições da semana',amount:97500,memberId:'',paymentMethod:'Pix'}],messages:[{id:'msg1',title:'Um convite para estarmos juntos',body:'Olá, {nome}! Esperamos você em nosso próximo culto. Será uma alegria estarmos juntos!',targetType:'all',targetId:'',groupLink:'',scheduledAt:new Date(Date.now()+86400000).toISOString(),status:'scheduled'}]};}
function InlineEditor({title,children,busy,onClose,kind}:{title:string;children:ReactNode;busy:boolean;onClose:()=>void;kind:string}){return <section id="inline-editor" className={'panel inline-editor editor-'+kind} aria-labelledby="inline-editor-title"><div className="editor-heading"><div><span className="eyebrow">JCR MARÍLIA · NESTA PÁGINA</span><h2 id="inline-editor-title">{title}</h2></div><Button variant="secondary" disabled={busy} onClick={onClose}><ChevronLeft size={16}/>Voltar</Button></div>{children}</section>}
export default function Dashboard(){
 const [real,setReal]=useState<Data>(emptyData),[demo,setDemo]=useState(false),[page,setPage]=useState(()=>location.hash.slice(1)||'overview'),[mobile,setMobile]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false),[toast,setToast]=useState(''),[activeForm,setActiveForm]=useState<string|null>(null),[edit,setEdit]=useState<any>(null),[month,setMonth]=useState(today().slice(0,7)),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[selected,setSelected]=useState(''),[draft,setDraft]=useState<Record<string,string>>({}),[qr,setQr]=useState(''),[person,setPerson]=useState(''),[messageTarget,setMessageTarget]=useState('all'),[dispatch,setDispatch]=useState<Message|null>(null),[clock,setClock]=useState(Date.now()),[calendarDate,setCalendarDate]=useState('');
 const me:Me=(real as any).me||null;const podeFin=!me||me.role!=='equipe';const d=demo?{...getDemo(),formUrl:real.formUrl,settings:real.settings}:real;const active=sortMembers(d.members.filter(m=>!m.archived));const rows=report(d,month);const totalPossible=rows.reduce((n,r)=>n+r.total,0),totalPresent=rows.reduce((n,r)=>n+r.present,0);const presence=totalPossible?Math.round(totalPresent/totalPossible*100):0;const selectedService=d.services.find(s=>s.id===selected);const selectedMembers=selectedService?active.filter(m=>eligible(m,selectedService)):[];const closed=d.services.filter(s=>s.date<=today()).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));const last=closed[0];const absent=last?active.filter(m=>eligible(m,last)&&statusFor(m,last,d.attendance)==='absent'):[];const income=d.transactions.filter(t=>t.date.startsWith(month)&&t.kind==='income').reduce((s,t)=>s+t.amount,0);const expense=d.transactions.filter(t=>t.date.startsWith(month)&&t.kind==='expense').reduce((s,t)=>s+t.amount,0);const next=d.services.filter(s=>s.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];const due=d.messages.filter(m=>m.status==='scheduled'&&new Date(m.scheduledAt).getTime()<=clock);
 useEffect(()=>{reload();const interval=setInterval(()=>setClock(Date.now()),30000);return()=>clearInterval(interval)},[]);
 async function reload(){try{const r=await fetch(API+'/data',{cache:'no-store'});const j:any=await r.json();if(r.status===401){location.reload();return;}if(!r.ok)throw new Error(j.error||'Não foi possível carregar.');setReal({...j,settings:{...j.settings,name:j.settings.name==='Igreja JCR'?'JCR Marília':j.settings.name}});setError('')}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{setDraft({});},[selected]);
 useEffect(()=>{if(activeForm==='share'&&d.formUrl)QRCode.toDataURL(d.formUrl,{width:600,margin:2,color:{dark:'#142d50',light:'#ffffff'}}).then(setQr).catch(()=>setToast('Não foi possível gerar o QR code.'));},[activeForm,d.formUrl]);
 useEffect(()=>{if(!activeForm&&!dispatch)return;const frame=requestAnimationFrame(()=>{document.getElementById('inline-editor')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});return()=>cancelAnimationFrame(frame)},[activeForm,dispatch?.id]);
 function navigate(p:string){history.replaceState(null,'',p==='overview'?location.pathname:'#'+p);setPage(p);setMobile(false);setQuery('');setFilter('all');setActiveForm(null);setDispatch(null)}
 function open(type:string,item:any=null){if(demo&&type!=='share'&&type!=='help'){setDemo(false);setToast('Agora você está usando seus dados reais.');item=null;}setEdit(item);setDispatch(null);setMobile(false);setActiveForm(type)}
 async function mutate(action:string,data:any,close=true){if(demo){setToast('Saia da demonstração para alterar seus dados.');return false;}setBusy(true);try{const r=await fetch(API+'/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data})});const j:any=await r.json();if(r.status===401){location.reload();return false;}if(!r.ok)throw new Error(j.error||'Não foi possível salvar.');await reload();if(close)setActiveForm(null);setToast('Alterações salvas com sucesso.');return true;}catch(e){setToast((e as Error).message);return false;}finally{setBusy(false)}}
 function handleForm(e:FormEvent<HTMLFormElement>,action:string,transform?:(v:any)=>any){e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));mutate(action,transform?transform(v):v)}
 function exportMembers(){downloadCSV('membros.csv',[['Nome','WhatsApp','E-mail','Nascimento','Ministério','Perfil','Data de entrada','Recebe mensagens'],...active.map(m=>[m.name,m.phone,m.email,m.birthDate,m.area,m.status==='member'?'Frequentante':'Visitante',m.joinedDate,m.consent?'Sim':'Não'])]);}
 function exportReport(){downloadCSV('presenca-'+month+'.csv',[['Relatório de presença',monthLabel(month)],['Nome','Cultos elegíveis','Presenças','Faltas','Justificadas','Presença (%)'],...rows.filter(r=>!person||r.member.id===person).map(r=>[r.member.name,r.total,r.present,r.absent,r.excused,r.total?r.rate:'Sem cultos'])]);}
 async function copy(v:string){try{await navigator.clipboard.writeText(v);setToast('Copiado para a área de transferência.')}catch{setToast('Selecione e copie o texto do campo.')}}
 function wa(m:Member,text:string){if(!m.phone||!m.consent){setToast('Este cadastro precisa de telefone e autorização para mensagens.');return;}const digits=m.phone.replace(/\D/g,'');window.open('https://wa.me/'+(digits.length<=11?'55':'')+digits+'?text='+encodeURIComponent(text.replaceAll('{nome}',m.name.split(' ')[0])),'_blank','noopener,noreferrer')}
 const missingText=(d.settings as any).missingText||'Olá, {nome}! Sentimos sua falta no culto. Esperamos que esteja tudo bem com você. Estamos aqui se precisar. Será uma alegria ter você conosco novamente!';
 function valueFor(id:string){return draft[id]??d.attendance.find(a=>a.serviceId===selected&&a.memberId===id)?.value??'present'}
 async function saveAttendance(close=false){if(!selectedService)return;const ok=await mutate('attendance.save',{serviceId:selected,values:selectedMembers.map(m=>({memberId:m.id,value:valueFor(m.id)})),close});if(ok)setDraft({})}
 const formTitle:Record<string,string>={member:edit?'Editar cadastro':'Uma nova pessoa na comunidade',service:edit?'Editar culto':'Agendar um culto',transaction:edit?'Editar lançamento':'Novo lançamento financeiro',message:'Programar uma mensagem',share:'Um convite para fazer parte',close:'Encerrar a chamada',help:'Como usar o painel JCR Marília',archive:'Arquivar cadastro',deleteTransaction:'Excluir lançamento',deleteService:'Excluir culto'};
 return <div className="app-shell">
 {mobile&&<button className="sidebar-shade" aria-label="Fechar menu" onClick={()=>setMobile(false)}/>}
 <aside className={'sidebar '+(mobile?'is-open':'')}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('overview')}}><span>JCR Marília<span className="brand-sub">GESTÃO DA IGREJA</span></span></a><div className="workspace"><div className="church-square"><Church size={20}/></div><div><strong>{d.settings.name}</strong><small>Área administrativa</small></div><span className="workspace-dot"/></div><p className="nav-caption">COMUNIDADE</p><nav>{nav.filter(n=>n.id!=='finance'||podeFin).map(n=><button key={n.id} className={'nav-item '+(page===n.id?'active':'')} onClick={()=>navigate(n.id)}><n.icon size={19}/><span>{n.label}</span>{n.id==='messages'&&due.length>0&&<i>{due.length}</i>}</button>)}</nav>
  <nav className="sidebar-shortcuts" aria-label="Links de gestão">
    <p className="nav-caption">LINKS DE GESTÃO</p>
    <a className="nav-item" href="/cadastro">
      <UserPlus size={17}/><span>Cadastro de visitantes</span><ArrowUpRight className="shortcut-arrow" size={14}/>
    </a>
    <a className="nav-item" href="/testes/">
      <PlayCircle size={17}/><span>Ambiente de testes</span><ArrowUpRight className="shortcut-arrow" size={14}/>
    </a>
    <a className={'nav-item '+(page==='avaliacoes'?'active':'')} href="#avaliacoes" onClick={e=>{e.preventDefault();navigate('avaliacoes')}}>
      <BarChart3 size={17}/><span>Avaliações dos testes</span><ArrowUpRight className="shortcut-arrow" size={14}/>
    </a>
    <a className="nav-item" href="/hub">
      <LinkIcon size={17}/><span>Todos os links</span><ArrowUpRight className="shortcut-arrow" size={14}/>
    </a>
  </nav>
  <div className="sidebar-bottom"><div className="care-card"><span className="care-icon"><Heart size={17}/></span><strong>Cada pessoa importa.</strong><p>Uma igreja mais próxima começa com cuidado.</p><button onClick={()=>open('share')}>Convidar para o cadastro <ArrowUpRight size={15}/></button></div><button className={'nav-item '+(page==='settings'?'active':'')} onClick={()=>navigate('settings')}><Settings size={19}/><span>Configurações</span></button><button className="nav-item muted" onClick={()=>setDemo(!demo)}><PlayCircle size={18}/><span>{demo?'Usar meus dados':'Ver demonstração'}</span></button><div className="sidebar-profile"><div className="profile-avatar">{initials(me?.name||'AD')}</div><div><strong>{me?.name||'Administração'}</strong><small><span/> {PAPEIS[me?.role||'']||'Acesso restrito'}</small></div><a href="#" title="Sair" onClick={async e=>{e.preventDefault();await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});location.reload()}}><LogOut size={17}/></a></div></div></aside>
 <div className="main-shell"><header className="topbar"><div><button className="icon-btn mobile-toggle" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu size={22}/></button><span className="breadcrumb">Comunidade <ChevronRight size={13}/> <b>{(page==='avaliacoes'?'Avaliações dos testes':nav.find(n=>n.id===page)?.label||'Configurações')}</b></span></div><div className="topbar-right"><span className="date-top"><CalendarDays size={15}/>{new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric',timeZone:'America/Sao_Paulo'})}</span><button className="icon-btn" title="Ajuda" onClick={()=>open('help')}><Info size={19}/></button><div className="profile-avatar small" title={me?.name}>{initials(me?.name||'AD')}</div></div></header>
 <main>
 {demo&&<div className="notice demo"><Info size={17}/><span><b>Modo demonstração.</b> Pessoas e valores fictícios para conhecer o painel.</span><button onClick={()=>setDemo(false)}>Usar meus dados <ArrowRight size={14}/></button></div>}
 {error&&!demo&&<div className="notice error"><AlertCircle size={18}/><span>{error}</span><button onClick={reload}>Tentar novamente</button></div>}
 {loading&&!demo&&<div className="notice"><RefreshCw size={16} className="spin"/>Carregando seus dados…</div>}
 <div className="page-heading"><div><div className="eyebrow">{page==='overview'?'BEM-VINDO À JCR MARÍLIA':'CUIDADO EM CADA DETALHE'}</div><h1>{(page==='avaliacoes'?'Avaliações dos testes':nav.find(n=>n.id===page)?.label||'Configurações')}</h1><p>{{avaliacoes:'O que os participantes acharam do ambiente de testes.',overview:'Um olhar atento para cuidar de cada pessoa.',members:'Pessoas, histórias e uma comunidade que cresce junta.',attendance:'Registre os encontros. Perceba quem precisa de cuidado.',reports:'Acompanhe a presença e fortaleça os vínculos.',finance:'Transparência e organização a serviço da igreja.',messages:'A palavra certa, com carinho, no momento certo.',settings:'As informações e os cuidados da JCR Marília em um só lugar.'}[page]}</p></div><div className="heading-actions">{page==='overview'&&<><Button variant="secondary" onClick={()=>open('share')}><QrCode size={17}/>Compartilhar cadastro</Button><Button onClick={()=>open('member')}><Plus size={18}/>Novo membro</Button></>}{page==='members'&&<><Button variant="secondary" onClick={()=>open('share')}><QrCode size={17}/>Link e QR code</Button><Button onClick={()=>open('member')}><Plus size={18}/>Novo membro</Button></>}{page==='attendance'&&<Button onClick={()=>open('service')}><Plus size={17}/>Novo culto</Button>}{page==='reports'&&<><Button variant="secondary" onClick={()=>window.print()}><Printer size={16}/>Imprimir</Button><Button onClick={exportReport}><Download size={16}/>Exportar relatório</Button></>}{page==='finance'&&<><Button variant="secondary" onClick={()=>downloadCSV('financeiro-'+month+'.csv',[['Data','Descrição','Tipo','Categoria','Valor (R$)','Pagamento'],...d.transactions.filter(t=>t.date.startsWith(month)).map(t=>[t.date,t.description,t.kind==='income'?'Entrada':'Saída',t.category,(t.amount/100).toFixed(2),t.paymentMethod])])}><Download size={16}/>Exportar</Button><Button onClick={()=>open('transaction')}><Plus size={18}/>Novo lançamento</Button></>}{page==='messages'&&<Button onClick={()=>{setMessageTarget('all');open('message')}}><Plus size={18}/>Programar mensagem</Button>}</div></div>
 {activeForm&&<InlineEditor key={`${activeForm}:${edit?.id||"new"}`} title={formTitle[activeForm]} busy={busy} onClose={()=>setActiveForm(null)} kind={activeForm}>
 {activeForm==='member'&&<form onSubmit={e=>handleForm(e,'member.save',v=>({...v,id:edit?.id,consent:v.consent==='on'?1:0}))}><div className="form-grid"><Field label="Nome completo *" full><input name="name" autoFocus required minLength={3} maxLength={120} defaultValue={edit?.name} placeholder="Como a pessoa se chama?"/></Field><Field label="WhatsApp com DDD"><input name="phone" type="tel" maxLength={30} defaultValue={edit?.phone} placeholder="(14) 99999-9999"/></Field><Field label="E-mail"><input name="email" type="email" defaultValue={edit?.email}/></Field><Field label="Data de nascimento"><input name="birthDate" type="date" max={today()} defaultValue={edit?.birthDate}/></Field><Field label="Data de entrada na igreja *"><input name="joinedDate" type="date" max={today()} required defaultValue={edit?.joinedDate||today()}/></Field><Field label="Perfil"><select name="status" defaultValue={edit?.status||'member'}><option value="member">Frequentante</option><option value="visitor">Visitante</option></select></Field><Field label="Ministério / equipe"><input name="area" maxLength={120} placeholder="Ex.: Louvor, recepção…" defaultValue={edit?.area}/></Field><Field label="Observações internas" full><textarea name="notes" rows={3} maxLength={3000} defaultValue={edit?.notes} placeholder="Informações úteis para acolher melhor"/></Field><label className="check-label full"><input name="consent" type="checkbox" defaultChecked={!!edit?.consent}/><span>A pessoa autorizou receber mensagens da igreja.</span></label>{Number((d.settings as any).inactivityWeeks)>0&&<p className="form-note full">Frequentantes que faltarem a todos os cultos por {(d.settings as any).inactivityWeeks} semanas, sem alteração no cadastro, são arquivados automaticamente. Salvar o cadastro reinicia essa contagem.</p>}</div><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button type="submit" disabled={busy}>{busy?'Salvando…':edit?'Salvar alterações':'Cadastrar pessoa'}</Button></div></form>}
 {activeForm==='service'&&<form onSubmit={e=>handleForm(e,'service.save',v=>({...v,id:edit?.id}))}><div className="form-grid"><Field label="Nome do encontro *" full><input name="title" autoFocus required minLength={3} maxLength={120} placeholder="Ex.: Culto da Família" defaultValue={edit?.title}/></Field><Field label="Data *"><input name="date" type="date" required defaultValue={edit?.date||calendarDate||today()}/></Field><Field label="Horário *"><input name="time" type="time" required defaultValue={edit?.time||'10:00'}/></Field><p className="form-note full">Na chamada, marque apenas quem faltou ou justificou: quem não for marcado conta como presente. O culto de domingo é criado sozinho toda semana. Visitantes não entram na chamada de membros.</p></div><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button type="submit" disabled={busy}>{busy?'Salvando…':edit?'Salvar culto':'Criar culto'}</Button></div></form>}
 {activeForm==='close'&&<><p className="editor-copy">Você marcou <b>{selectedMembers.filter(m=>valueFor(m.id)==='absent').length} faltas</b> e <b>{selectedMembers.filter(m=>valueFor(m.id)==='excused').length} justificativas</b>. As outras <b>{selectedMembers.filter(m=>valueFor(m.id)==='present').length} pessoas</b> ficam registradas como presentes. Você poderá reabrir a chamada para corrigir.</p><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Voltar para a chamada</Button><Button disabled={busy} onClick={()=>saveAttendance(true)}>{busy?'Salvando…':'Confirmar encerramento'}</Button></div></>}
 {activeForm==='transaction'&&<form onSubmit={e=>handleForm(e,'transaction.save',v=>({...v,id:edit?.id,amount:moneyToCents(v.amount),memberId:v.memberId||null}))}><div className="form-grid"><Field label="Tipo *"><select name="kind" defaultValue={edit?.kind||'income'}><option value="income">Entrada</option><option value="expense">Saída</option></select></Field><Field label="Valor (R$) *"><input name="amount" required inputMode="decimal" pattern="[0-9.,]+" placeholder="0,00" defaultValue={edit?(edit.amount/100).toFixed(2).replace('.',','):''}/></Field><Field label="Descrição *" full><input name="description" required minLength={2} maxLength={200} placeholder="Ex.: Ofertas do Culto da Família" defaultValue={edit?.description}/></Field><Field label="Data *"><input name="date" type="date" required defaultValue={edit?.date||today()}/></Field><Field label="Categoria *"><select name="category" defaultValue={edit?.category||'Dízimos'}>{['Dízimos','Ofertas','Doações','Missões','Aluguel','Água e energia','Manutenção','Materiais','Ação social','Eventos','Outras entradas','Outras saídas'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Forma de pagamento"><select name="paymentMethod" defaultValue={edit?.paymentMethod||'Pix'}>{['Pix','Dinheiro','Transferência','Cartão','Boleto','Outro'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Contribuinte (opcional)"><select name="memberId" defaultValue={edit?.memberId||''}><option value="">Não identificar</option>{active.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></Field></div><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button type="submit" disabled={busy}>{busy?'Salvando…':'Salvar lançamento'}</Button></div></form>}
 {activeForm==='message'&&<form onSubmit={e=>handleForm(e,'message.save',v=>({...v,scheduledAt:new Date(v.scheduledAt+'-03:00').toISOString()}))}><div className="form-grid"><Field label="Título interno *" full><input name="title" required minLength={3} maxLength={140} defaultValue={messageTarget==='absent'?'Sentimos sua falta':''} placeholder="Ex.: Convite para o culto de domingo"/></Field><Field label="Destinatário *" full><select name="targetType" value={messageTarget} onChange={e=>setMessageTarget(e.target.value)}><option value="all">Toda a comunidade · individualmente</option><option value="member">Uma pessoa</option><option value="absent">Faltantes de um culto</option><option value="group">Grupo da igreja</option><option value="broadcast">Lista de transmissão</option></select></Field>{messageTarget==='member'&&<Field label="Pessoa *" full><select name="targetId" required><option value="">Selecione uma pessoa</option>{active.map(m=><option key={m.id} value={m.id}>{m.name}{!m.phone||!m.consent?' (contato pendente)':''}</option>)}</select></Field>}{messageTarget==='absent'&&<Field label="Culto *" full><select name="targetId" required><option value="">Selecione um culto</option>{closed.map(s=><option key={s.id} value={s.id}>{fmtDate(s.date)} · {s.title}</option>)}</select></Field>}{messageTarget==='group'&&<Field label="Link do grupo (opcional)" full><input name="groupLink" type="url" placeholder="https://chat.whatsapp.com/..." defaultValue={d.settings.groupLink}/></Field>}<Field label="Data e horário de Brasília *" full><input name="scheduledAt" type="datetime-local" required defaultValue={today()+'T18:00'}/></Field><Field label="Sua mensagem *" full><textarea name="body" required minLength={3} rows={5} maxLength={4000} defaultValue={edit?.body||(messageTarget==='absent'?missingText:'')} placeholder="Escreva uma mensagem de acolhimento…"/></Field><p className="form-note full">Use {'{nome}'} para personalizar mensagens individuais. O agendamento organiza a fila; a entrega exige ação manual no WhatsApp. Para grupos e transmissão, copie e cole no aplicativo.</p></div><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button type="submit" disabled={busy}>{busy?'Salvando…':'Salvar agendamento'}</Button></div></form>}
 {activeForm==='share'&&<div className="share-content"><p>Um formulário simples para acolher quem está chegando.<br/>A pessoa preenche pelo celular e o cadastro aparece no painel.</p><div className="qr-frame">{qr?<img src={qr} alt="QR code para o formulário de cadastro de visitantes"/>:<QrCode size={120}/>}</div><div className="share-link"><input aria-label="Link do formulário" readOnly value={d.formUrl||real.formUrl||'Carregando o endereço do cadastro…'}/><button className="icon-btn" title="Copiar link" disabled={!d.formUrl} onClick={()=>copy(d.formUrl)}><Copy size={19}/></button></div><div className="share-buttons"><Button disabled={!d.formUrl} onClick={()=>copy(d.formUrl)}><LinkIcon size={16}/>Copiar link</Button><Button variant="secondary" disabled={!qr} onClick={()=>{const a=document.createElement('a');a.href=qr;a.download='qr-code-cadastro.png';a.click()}}><Download size={16}/>Baixar QR code</Button></div>{d.formUrl&&<a className="text-btn" href={d.formUrl} target="_blank" rel="noreferrer">Abrir formulário <ExternalLink size={14}/></a>}<span className="share-secure"><ShieldCheck size={14}/>O formulário permite apenas enviar um cadastro.</span></div>}
 {activeForm==='archive'&&<><p className="editor-copy">Arquivar <b>{edit?.name}</b>? A pessoa deixa de aparecer nas novas chamadas. Seu cadastro, presenças anteriores e lançamentos são preservados. Você pode restaurar depois.</p><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button disabled={busy} onClick={()=>mutate('member.archive',{id:edit.id,archived:true})}>Arquivar cadastro</Button></div></>}
 {activeForm==='deleteTransaction'&&<><p className="editor-copy">Excluir o lançamento <b>{edit?.description}</b>, de <b>{currency(edit?.amount||0)}</b>? Os totais do período serão recalculados.</p><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button disabled={busy} variant="danger" onClick={()=>mutate('transaction.delete',{id:edit.id})}>Excluir lançamento</Button></div></>}
 {activeForm==='deleteService'&&<><p className="editor-copy">Excluir <b>{edit?.title}</b> de {edit?fmtDate(edit.date,{day:'2-digit',month:'long'}):''}? A chamada desse culto também será apagada.{edit?.auto?' Como é um culto de domingo automático, ele não será criado de novo nessa data.':''}</p><div className="form-actions"><Button variant="secondary" onClick={()=>setActiveForm(null)}>Cancelar</Button><Button disabled={busy} variant="danger" onClick={async()=>{if(await mutate('service.delete',{id:edit.id}))setSelected('')}}>Excluir culto</Button></div></>}
 {activeForm==='help'&&<div className="help-content">{[['1','Conheça sua comunidade','Cadastre frequentantes ou compartilhe o formulário de visitantes. Novos visitantes aparecem em Membros e podem ser promovidos a frequentantes.'],['2','Registre cada encontro','O culto de domingo aparece sozinho. Na chamada, marque só quem faltou ou justificou: quem não for marcado conta como presente. Encerre para ver a lista de faltantes.'],['3','Transforme presença em cuidado','Veja relatórios mensais, exporte a lista de faltantes e abra mensagens individuais no WhatsApp para contatos autorizados.'],['4','Organize finanças e comunicação','Registre entradas e saídas, exporte os relatórios e programe sua fila de mensagens. O envio pelo WhatsApp é manual.']].map(([n,t,v])=><div key={n}><span>{n}</span><section><h3>{t}</h3><p>{v}</p></section></div>)}</div>}
 </InlineEditor>}
 {dispatch&&<InlineEditor title={dispatch.title} busy={busy} onClose={()=>setDispatch(null)} kind="dispatch"><div className="dispatch-body"><div className="message-preview">{dispatch.body}</div>{['group','broadcast'].includes(dispatch.targetType)?<><p>Copie o texto e abra seu {dispatch.targetType==='group'?'grupo':'WhatsApp para escolher uma lista de transmissão'}. A mensagem só será enviada quando você confirmar no aplicativo.</p><div className="share-buttons"><Button onClick={()=>copy(dispatch.body.replaceAll('{nome}','pessoal'))}><Copy size={16}/>Copiar mensagem</Button><a className="btn secondary" href={dispatch.targetType==='group'&&dispatch.groupLink?dispatch.groupLink:'https://wa.me/?text='+encodeURIComponent(dispatch.body.replaceAll('{nome}','pessoal'))} target="_blank" rel="noreferrer"><ExternalLink size={16}/>Abrir WhatsApp</a></div></>:<><p>Abra uma conversa por vez e confirme o envio no WhatsApp. Contatos sem autorização ou telefone aparecem desabilitados.</p><div className="dispatch-recipients">{active.filter(m=>dispatch.targetType==='member'?m.id===dispatch.targetId:dispatch.targetType==='absent'?(()=>{const s=d.services.find(s=>s.id===dispatch.targetId);return s&&eligible(m,s)&&statusFor(m,s,d.attendance)==='absent'})():true).map((m,i)=><div key={m.id}><div className="person-cell"><Avatar name={m.name} index={i}/><div><b>{m.name}</b><small>{m.phone||'Sem telefone'}{!m.consent?' · Sem autorização':''}</small></div></div><Button variant="secondary" disabled={!m.phone||!m.consent} onClick={()=>wa(m,dispatch.body)}><MessageCircle size={16}/>Abrir</Button></div>)}</div></>}<p className="form-note">Abrir uma conversa não confirma a entrega. Marque como concluída somente depois de terminar os envios.</p></div><div className="form-actions"><Button variant="secondary" onClick={()=>setDispatch(null)}>Voltar</Button><Button disabled={busy} onClick={async()=>{if(await mutate('message.status',{id:dispatch.id,status:'completed'},false))setDispatch(null)}}><CheckCheck size={17}/>Confirmar que enviei</Button></div></InlineEditor>}

 {page==='overview'&&<>
 <div className="stats-grid"><Stat label="Membros da comunidade" value={active.filter(m=>m.status==='member').length.toString()} icon={Users} note={`${active.filter(m=>m.status==='visitor').length} visitantes para acolher`} tone="mint"/><Stat label="Presença neste mês" value={totalPossible?presence+'%':'—'} icon={CalendarCheck} note={totalPossible?`${totalPresent} presenças registradas`:'Aparece depois do primeiro culto'} tone="blue"/><Stat label="Sentimos sua falta" value={absent.length.toString()} icon={Heart} note={last?'Pessoas ausentes no último culto':'Acompanhe após o primeiro culto'} tone="orange" onClick={()=>{navigate('attendance');if(last)setSelected(last.id)}}/><Stat label="Saldo do mês" value={currency(income-expense)} icon={Wallet} note={`${currency(income)} em entradas`} tone="purple"/></div>
 <div className="dashboard-middle"><section className="panel attendance-chart"><div className="panel-heading"><div><h2>A presença que aproxima</h2><p>Participação nos encontros da comunidade</p></div><Month value={month} onChange={setMonth}/></div><div className="chart-legend"><span><i/>Presenças por culto</span><b>{totalPossible?presence+'%':'—'} <small>de participação no mês</small></b></div><PresenceChart data={d} month={month}/><div className="chart-bottom"><span><Leaf size={14}/>Mais que números, pessoas que caminham juntas.</span><button className="text-btn" onClick={()=>navigate('reports')}>Ver relatório <ArrowRight size={15}/></button></div></section>
 <section className="next-service"><div className="next-top"><span><span/> PRÓXIMO ENCONTRO</span><Church size={25}/></div><div className="service-illustration"><div className="arch arch1"/><div className="arch arch2"/><div className="arch arch3"/><span>✝</span></div><div className="next-content"><h2>{next?.title||'Um novo encontro começa aqui.'}</h2><p>{next?<><CalendarDays size={15}/>{fmtDate(next.date,{weekday:'long',day:'2-digit',month:'long'})} <span>·</span> {next.time}</>:'Organize o próximo culto e prepare a chamada.'}</p><button onClick={()=>{if(next){navigate('attendance');setSelected(next.id)}else open('service')}}>{next?'Abrir lista de presença':'Agendar primeiro culto'}<ArrowRight size={18}/></button></div></section></div>
 <div className="dashboard-lower"><section className="panel recent-panel"><div className="panel-heading"><div><h2>Gente que chegou para somar <span className="count-label">{active.filter(m=>m.source==='self').length}</span></h2><p>Os cadastros mais recentes da comunidade</p></div><button className="text-btn" onClick={()=>navigate('members')}>Ver todos <ArrowRight size={15}/></button></div>{active.length?<div className="table-wrap"><table><thead><tr><th>NOME</th><th>PERFIL</th><th>CADASTRO</th><th/></tr></thead><tbody>{[...active].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,4).map((m,i)=><tr key={m.id}><td><div className="person-cell"><Avatar name={m.name} index={i}/><div><strong>{m.name}</strong><small>{m.area||'Comunidade'}</small></div></div></td><td><Pill tone={m.status==='member'?'green':'amber'}>{m.status==='member'?'Frequentante':'Visitante'}</Pill></td><td className="muted-text">{m.source==='self'?'Pelo formulário':'Manual'}</td><td><button className="icon-btn" title={'Editar '+m.name} onClick={()=>open('member',m)}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>:<Empty title="Toda comunidade começa com pessoas" text="Cadastre o primeiro membro ou compartilhe o formulário com a igreja." action={<Button variant="secondary" onClick={()=>open('member')}><UserPlus size={16}/>Adicionar pessoa</Button>}/>}</section>
 <section className="panel care-panel"><div className="panel-heading"><div><h2>Pequenos gestos, grandes vínculos</h2><p>Há sempre uma forma de estar mais perto.</p></div></div><button className="quick-action" onClick={()=>{navigate('attendance');if(last)setSelected(last.id)}}><span className="quick-icon peach"><Heart size={19}/></span><div><strong>Sentimos sua falta</strong><small>{absent.length?`${absent.length} pessoas aguardam seu carinho`:'Veja os ausentes do último culto'}</small></div><ChevronRight size={17}/></button><button className="quick-action" onClick={()=>{setMessageTarget('all');open('message')}}><span className="quick-icon sage"><MessageCircle size={19}/></span><div><strong>Uma mensagem de cuidado</strong><small>Prepare um convite ou uma palavra</small></div><ChevronRight size={17}/></button><button className="quick-action" onClick={()=>open('share')}><span className="quick-icon lavender"><QrCode size={19}/></span><div><strong>Portas abertas para acolher</strong><small>Compartilhe o cadastro de visitantes</small></div><ChevronRight size={17}/></button><div className="verse">“Assim nós, que somos muitos, somos um só corpo em Cristo.”<span>ROMANOS 12:5</span></div></section></div>
 </>}
 {page==='members'&&<section className="panel"><div className="toolbar"><div className="tabs">{[['all','Todos',active.length],['member','Frequentantes',active.filter(m=>m.status==='member').length],['visitor','Visitantes',active.filter(m=>m.status==='visitor').length],['archived','Arquivados',d.members.filter(m=>m.archived).length]].map(([id,label,n])=><button className={filter===id?'active':''} key={id} onClick={()=>setFilter(String(id))}>{label}<span>{n}</span></button>)}</div><div className="tools"><label className="search"><Search size={17}/><input aria-label="Buscar membros" placeholder="Buscar por nome ou telefone" value={query} onChange={e=>setQuery(e.target.value)}/></label><button className="icon-btn" title="Exportar membros" onClick={exportMembers}><Download size={18}/></button></div></div><div className="table-wrap"><table><thead><tr><th>NOME <span>↑</span></th><th>CONTATO</th><th>MINISTÉRIO</th><th>PERFIL</th><th>ENTRADA</th><th/></tr></thead><tbody>{sortMembers(d.members).filter(m=>(filter==='archived'?m.archived:!m.archived&&(filter==='all'||m.status===filter))&&(m.name.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))||m.phone.includes(query))).map((m,i)=><tr key={m.id}><td><div className="person-cell"><Avatar name={m.name} index={i}/><div><strong>{m.name}</strong><small>{m.archived&&m.archivedReason==='auto'?'Arquivado após '+(m.archivedWeeks||8)+' semanas sem presença':m.source==='self'?'Cadastro pelo formulário':'Cadastro manual'}</small></div></div></td><td><div className="stack"><span>{m.phone||'Sem telefone'}</span><small>{m.email}</small></div></td><td>{m.area||'—'}</td><td><Pill tone={m.archived?'gray':m.status==='member'?'green':'amber'}>{m.archived?'Arquivado':m.status==='member'?'Frequentante':'Visitante'}</Pill></td><td>{fmtDate(m.joinedDate)}</td><td><div className="row-actions"><button className="icon-btn" title="Editar cadastro" onClick={()=>open('member',m)}><Pencil size={16}/></button><button className="icon-btn" title={m.archived?'Restaurar cadastro':'Arquivar cadastro'} onClick={()=>m.archived?mutate('member.archive',{id:m.id,archived:false}):open('archive',m)}>{m.archived?<RefreshCw size={16}/>:<Archive size={16}/>}</button></div></td></tr>)}</tbody></table></div>{!d.members.length&&<Empty title="Vamos conhecer sua comunidade?" text="Cadastre manualmente ou deixe que cada pessoa preencha o formulário." action={<Button onClick={()=>open('member')}><Plus size={17}/>Cadastrar primeiro membro</Button>}/>}<div className="table-foot"><span>Organizado em ordem alfabética · {d.members.length} cadastros</span><ShieldCheck size={14}/>Informações restritas à gestão</div></section>}
 {page==='attendance'&&<div className="attendance-layout"><div className="calendar-column"><section className="panel calendar-panel"><div className="calendar-heading"><b>{monthLabel(month)}</b><div><button className="icon-btn" aria-label="Mês anterior" onClick={()=>{setMonth(shiftMonth(month,-1));setCalendarDate('')}}><ChevronLeft size={17}/></button><button className="icon-btn" aria-label="Próximo mês" onClick={()=>{setMonth(shiftMonth(month,1));setCalendarDate('')}}><ChevronRight size={17}/></button></div></div><Calendar month={month} services={d.services} selected={calendarDate} onSelect={v=>{setCalendarDate(v);const s=d.services.find(s=>s.date===v);if(s)setSelected(s.id)}}/><div className="calendar-key"><span><i/>Culto agendado</span><span><i/>Chamada encerrada</span></div></section><section className="panel services-panel"><div className="panel-heading"><h2>Encontros {calendarDate?fmtDate(calendarDate):'do mês'}</h2>{calendarDate&&<button className="text-btn" onClick={()=>setCalendarDate('')}>Ver todos</button>}</div>{d.services.filter(s=>s.date.startsWith(month)&&(!calendarDate||s.date===calendarDate)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(s=><button key={s.id} className={'service-row '+(selected===s.id?'selected':'')} onClick={()=>setSelected(s.id)}><span className="date-tile"><small>{fmtDate(s.date,{month:'short'}).replace('.','')}</small><b>{s.date.slice(8)}</b></span><div><strong>{s.title}</strong><small>{s.time} <span>·</span> {s.status==='closed'?'Chamada encerrada':'Chamada aberta'}</small></div><ChevronRight size={15}/></button>)}{!d.services.some(s=>s.date.startsWith(month)&&(!calendarDate||s.date===calendarDate))&&<p className="simple-empty">Nenhum culto neste período.<button className="text-btn" onClick={()=>open('service')}>Agendar encontro <Plus size={14}/></button></p>}</section></div><section className="panel attendance-list">{selectedService?<><div className="panel-heading"><div><Pill tone={selectedService.status==='closed'?'green':'amber'}>{selectedService.status==='closed'?'Chamada encerrada':'Chamada em aberto'}</Pill><h2 className="mt12">{selectedService.title}</h2><p>{fmtDate(selectedService.date,{weekday:'long',day:'2-digit',month:'long'})} · {selectedService.time}</p></div><div className="row-actions"><button className="icon-btn" title="Excluir culto" onClick={()=>open('deleteService',selectedService)}><Trash2 size={16}/></button>{selectedService.status==='closed'?<Button variant="secondary" disabled={busy} onClick={()=>mutate('service.reopen',{id:selected})}><RefreshCw size={15}/>Reabrir</Button>:<><button className="icon-btn" title="Editar culto" onClick={()=>open('service',selectedService)}><Pencil size={16}/></button><Button variant="secondary" onClick={()=>setDraft(Object.fromEntries(selectedMembers.map(m=>[m.id,'present'])))}><CheckCheck size={16}/>Todos presentes</Button></>}</div></div>{selectedService.status==='closed'&&<div className="attendance-summary"><div><b>{selectedMembers.filter(m=>statusFor(m,selectedService,d.attendance)==='present').length}</b><span>presentes</span></div><div><b>{selectedMembers.filter(m=>statusFor(m,selectedService,d.attendance)==='absent').length}</b><span>faltantes</span></div><div><b>{selectedMembers.filter(m=>statusFor(m,selectedService,d.attendance)==='excused').length}</b><span>justificadas</span></div></div>}<div className="toolbar compact"><label className="search"><Search size={16}/><input placeholder="Buscar uma pessoa" aria-label="Buscar pessoa na chamada" value={query} onChange={e=>setQuery(e.target.value)}/></label>{selectedService.status==='closed'&&<select aria-label="Filtrar presença" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todas as pessoas</option><option value="absent">Apenas faltantes</option><option value="present">Presentes</option><option value="excused">Justificadas</option></select>}</div><div className="attendance-people">{selectedMembers.filter(m=>m.name.toLowerCase().includes(query.toLowerCase())&&(filter==='all'||statusFor(m,selectedService,d.attendance)===filter)).map((m,i)=>{const st=selectedService.status==='closed'?statusFor(m,selectedService,d.attendance):valueFor(m.id);return <div key={m.id} className="attendance-person"><div className="person-cell"><Avatar name={m.name} index={i}/><div><strong>{m.name}</strong><small>{m.area||'Frequentante'}</small></div></div>{selectedService.status==='open'?<div className="attendance-buttons"><button title={st==='absent'?'Desmarcar falta':'Marcar falta'} className={st==='absent'?'missed':''} onClick={()=>setDraft({...draft,[m.id]:st==='absent'?'present':'absent'})}><X size={15}/><span>Faltou</span></button><button title="Justificar ausência" className={st==='excused'?'justified':''} onClick={()=>setDraft({...draft,[m.id]:st==='excused'?'present':'excused'})}><Clock size={15}/><span>Justificada</span></button></div>:<div className="row-actions"><Pill tone={st==='present'?'green':st==='absent'?'rose':'gray'}>{st==='present'?'Presente':st==='absent'?'Faltou':'Justificada'}</Pill>{st==='absent'&&<button className="icon-btn whatsapp" title="Abrir mensagem de cuidado no WhatsApp" disabled={!m.phone||!m.consent} onClick={()=>wa(m,missingText)}><MessageCircle size={18}/></button>}</div>}</div>})}{!selectedMembers.length&&<Empty title="Sua chamada está pronta para começar" text="Cadastre frequentantes com data de entrada até o dia deste culto." action={<Button variant="secondary" onClick={()=>open('member')}>Cadastrar membro</Button>}/>}</div>{selectedService.status==='open'?<div className="attendance-footer"><span><b>{selectedMembers.filter(m=>valueFor(m.id)==='present').length}</b> de {selectedMembers.length} presentes</span><div><Button variant="secondary" disabled={busy} onClick={()=>saveAttendance(false)}>Salvar rascunho</Button><Button disabled={busy} onClick={()=>setActiveForm('close')}>Encerrar chamada <Check size={16}/></Button></div></div>:<div className="attendance-footer closed-footer"><span><Heart size={16}/>Faltantes em ordem alfabética. Envie uma palavra de carinho.</span><button className="text-btn" onClick={()=>downloadCSV('faltantes-'+selectedService.date+'.csv',[['Nome','WhatsApp'],...selectedMembers.filter(m=>statusFor(m,selectedService,d.attendance)==='absent').map(m=>[m.name,m.phone])])}><Download size={15}/>Exportar faltantes</button></div>}</>:<Empty icon={CalendarDays} title="Cada encontro merece ser lembrado" text="Escolha um culto no calendário para fazer a chamada e acompanhar os faltantes." action={<Button onClick={()=>open('service')}><Plus size={16}/>Agendar culto</Button>}/>}</section></div>}
 {page==='reports'&&<><div className="report-filter"><Month value={month} onChange={setMonth}/><select aria-label="Pessoa do relatório" value={person} onChange={e=>setPerson(e.target.value)}><option value="">Toda a comunidade</option>{sortMembers(d.members.filter(m=>m.status==='member')).map(m=><option key={m.id} value={m.id}>{m.name}{m.archived?' (arquivado)':''}</option>)}</select><span><Info size={15}/>Quem não foi marcado com falta conta como presente.</span></div><div className="stats-grid report-stats"><Stat label="Cultos realizados" value={d.services.filter(s=>s.date.startsWith(month)&&s.date<=today()).length.toString()} icon={Church} note={monthLabel(month)} tone="mint"/><Stat label="Presenças registradas" value={rows.filter(r=>!person||r.member.id===person).reduce((n,r)=>n+r.present,0).toString()} icon={CalendarCheck} note="Nos cultos elegíveis do período" tone="blue"/><Stat label="Participação média" value={(()=>{const rs=rows.filter(r=>!person||r.member.id===person);const n=rs.reduce((n,r)=>n+r.total,0);return n?Math.round(rs.reduce((n,r)=>n+r.present,0)/n*100)+'%':'—'})()} icon={BarChart3} note="Presenças ÷ oportunidades de presença" tone="purple"/><Stat label="Ausências justificadas" value={rows.filter(r=>!person||r.member.id===person).reduce((n,r)=>n+r.excused,0).toString()} icon={Clock} note="Registradas separadamente das faltas" tone="orange"/></div><section className="panel"><div className="panel-heading"><div><h2>{person?'Histórico individual':'Pessoas por trás dos números'}</h2><p>{monthLabel(month)} · Ordem alfabética</p></div><Pill>{rows.length} frequentantes</Pill></div><div className="table-wrap"><table><thead><tr><th>PESSOA</th><th>CULTOS ELEGÍVEIS</th><th>PRESENÇAS</th><th>FALTAS</th><th>JUSTIFICADAS</th><th>PARTICIPAÇÃO</th></tr></thead><tbody>{rows.filter(r=>!person||r.member.id===person).map((r,i)=><tr key={r.member.id}><td><div className="person-cell"><Avatar name={r.member.name} index={i}/><strong>{r.member.name}</strong></div></td><td>{r.total}</td><td className="green-text">{r.present}</td><td>{r.absent}</td><td>{r.excused}</td><td><div className="progress-cell"><div><i style={{width:r.rate+'%'}}/></div><b>{r.total?r.rate+'%':'—'}</b></div></td></tr>)}</tbody></table></div>{!rows.length&&<Empty icon={BarChart3} title="O cuidado também tem história" text="Cadastre frequentantes e encerre as chamadas para acompanhar a presença mensal."/>}<div className="report-note"><Info size={16}/><p>Cada pessoa é considerada a partir da sua data de entrada. Entram todos os cultos já realizados: quem não foi marcado com falta ou justificativa conta como presente. Justificativas permanecem no total de oportunidades de presença.</p></div></section>{person&&<section className="panel individual-panel"><div className="panel-heading"><h2>Encontro por encontro</h2></div>{d.services.filter(s=>s.date<=today()&&s.date.startsWith(month)&&s.date>=(d.members.find(m=>m.id===person)?.joinedDate||'')).sort((a,b)=>a.date.localeCompare(b.date)).map(s=>{const m=d.members.find(m=>m.id===person)!;const st=statusFor(m,s,d.attendance);return <div className="history-row" key={s.id}><span>{fmtDate(s.date)} · {s.time}</span><b>{s.title}</b><Pill tone={st==='present'?'green':st==='absent'?'rose':'gray'}>{st==='present'?'Presente':st==='absent'?'Faltou':'Justificada'}</Pill></div>})}</section>}</>}
 {page==='finance'&&<><div className="report-filter"><Month value={month} onChange={setMonth}/><span><ShieldCheck size={15}/>Informações financeiras restritas à gestão.</span></div><div className="finance-stats"><Stat label="Entradas no mês" value={currency(income)} icon={ArrowDownLeft} note="Dízimos, ofertas e outras contribuições" tone="mint"/><Stat label="Saídas no mês" value={currency(expense)} icon={ArrowUpRight} note="Despesas e investimentos da igreja" tone="orange"/><Stat label="Resultado do mês" value={currency(income-expense)} icon={Wallet} note="Entradas menos saídas do período" tone="blue"/></div><section className="panel"><div className="toolbar"><div className="tabs">{[['all','Todos os lançamentos'],['income','Entradas'],['expense','Saídas']].map(([id,label])=><button key={id} className={filter===id?'active':''} onClick={()=>setFilter(id)}>{label}</button>)}</div><label className="search"><Search size={16}/><input aria-label="Buscar lançamentos" placeholder="Buscar lançamento" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="table-wrap"><table><thead><tr><th>DESCRIÇÃO</th><th>DATA</th><th>CATEGORIA</th><th>PAGAMENTO</th><th>VALOR</th><th/></tr></thead><tbody>{d.transactions.filter(t=>t.date.startsWith(month)&&(filter==='all'||t.kind===filter)&&t.description.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)).map(t=><tr key={t.id}><td><div className="person-cell"><span className={'transaction-icon '+t.kind}>{t.kind==='income'?<ArrowDownLeft size={19}/>:<ArrowUpRight size={19}/>}</span><div><strong>{t.description}</strong><small>{t.memberId?d.members.find(m=>m.id===t.memberId)?.name:t.kind==='income'?'Contribuição da comunidade':'Despesa da igreja'}</small></div></div></td><td>{fmtDate(t.date)}</td><td><Pill tone="gray">{t.category}</Pill></td><td>{t.paymentMethod}</td><td className={'amount '+(t.kind==='income'?'green-text':'')}>{t.kind==='income'?'+':'−'} {currency(t.amount)}</td><td><div className="row-actions"><button className="icon-btn" title="Editar lançamento" onClick={()=>open('transaction',t)}><Pencil size={15}/></button><button className="icon-btn" title="Excluir lançamento" onClick={()=>open('deleteTransaction',t)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>{!d.transactions.some(t=>t.date.startsWith(month))&&<Empty icon={Wallet} title="Organização para servir melhor" text="Registre dízimos, ofertas e despesas para gerar seu relatório financeiro mensal." action={<Button onClick={()=>open('transaction')}><Plus size={16}/>Primeiro lançamento</Button>}/>}<div className="table-foot"><span>{monthLabel(month)}</span><span>Saldo acumulado até o fim do mês: <b>{currency(d.transactions.filter(t=>t.date.slice(0,7)<=month).reduce((n,t)=>n+(t.kind==='income'?t.amount:-t.amount),0))}</b></span></div></section></>}
 {page==='messages'&&<><div className="notice whatsapp-notice"><MessageCircle size={20}/><div><b>Mensagens com o seu toque pessoal</b><p>Você programa e organiza por aqui. No horário, abra o WhatsApp e confirme o envio. O envio automático depende de uma integração de WhatsApp, ainda não conectada.</p></div><Pill tone="amber">Envio assistido</Pill></div><div className="message-metrics"><span><i className="green-dot"/><b>{d.messages.filter(m=>m.status==='scheduled').length}</b> programadas</span><span><CheckCheck size={16}/><b>{d.messages.filter(m=>m.status==='completed').length}</b> concluídas pela gestão</span><span><Clock size={16}/><b>{due.length}</b> prontas para enviar</span></div><section className="panel"><div className="toolbar"><div className="tabs">{[['all','Todas'],['scheduled','Programadas'],['completed','Concluídas'],['cancelled','Canceladas']].map(([id,label])=><button key={id} className={filter===id?'active':''} onClick={()=>setFilter(id)}>{label}</button>)}</div></div><div className="message-list">{d.messages.filter(m=>filter==='all'||m.status===filter).sort((a,b)=>a.scheduledAt.localeCompare(b.scheduledAt)).map(m=><article className="message-card" key={m.id}><span className="message-icon"><MessageCircle size={22}/></span><div className="message-content"><div><h3>{m.title}</h3><Pill tone={m.status==='completed'?'green':m.status==='cancelled'?'gray':new Date(m.scheduledAt).getTime()<=clock?'amber':'blue'}>{m.status==='completed'?'Envio confirmado':m.status==='cancelled'?'Cancelada':new Date(m.scheduledAt).getTime()<=clock?'Pronta para enviar':'Programada · manual'}</Pill></div><p>{m.body}</p><small><CalendarDays size={14}/>{new Date(m.scheduledAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}<span>·</span><Users size={14}/>{m.targetType==='member'?d.members.find(p=>p.id===m.targetId)?.name||'Pessoa arquivada':{all:'Toda a comunidade',absent:'Faltantes do culto selecionado',group:'Grupo da igreja',broadcast:'Lista de transmissão'}[m.targetType]}<span>·</span>Horário de Brasília</small></div>{m.status==='scheduled'&&<div className="message-actions"><Button variant="secondary" onClick={()=>{setActiveForm(null);setDispatch(m)}}><Send size={15}/>Preparar envio</Button><button className="text-btn muted" disabled={busy} onClick={()=>mutate('message.status',{id:m.id,status:'cancelled'})}>Cancelar</button></div>}</article>)}</div>{!d.messages.length&&<Empty icon={MessageCircle} title="Uma palavra pode aproximar" text="Prepare mensagens para pessoas, faltantes, grupos ou listas de transmissão." action={<Button onClick={()=>{setMessageTarget('all');open('message')}}><Plus size={16}/>Programar primeira mensagem</Button>}/>}</section><div className="message-tips"><div><Heart size={21}/><b>Sentimos sua falta</b><p>Uma mensagem de cuidado aos ausentes de um culto.</p><button className="text-btn" onClick={()=>{setMessageTarget('absent');open('message')}}>Usar este modelo <ArrowRight size={14}/></button></div><div><Church size={21}/><b>Vamos estar juntos?</b><p>Um convite acolhedor para o próximo encontro.</p><button className="text-btn" onClick={()=>{setMessageTarget('all');open('message',{body:'Olá, {nome}! Queremos convidar você para o nosso próximo culto. Sua presença torna nossa comunidade ainda mais especial!'})}}>Usar este modelo <ArrowRight size={14}/></button></div></div></>}
 {page==='avaliacoes'&&<Avaliacoes/>}
 {page==='settings'&&<div className="settings-grid"><section className="panel"><div className="panel-heading"><div><h2>A identidade da sua comunidade</h2><p>Essas informações aparecem no painel administrativo.</p></div><Church size={24}/></div><form className="form-grid padded" onSubmit={e=>handleForm(e,'settings.save',v=>({...v,autoSunday:v.autoSunday==='on'}))}><Field label="Nome da igreja" full><input name="name" required minLength={3} maxLength={120} defaultValue={d.settings.name}/></Field><Field label="Sigla"><input name="acronym" required maxLength={8} defaultValue={d.settings.acronym}/></Field><Field label="Endereço" full><input name="address" maxLength={250} defaultValue={d.settings.address}/></Field><Field label="Link do grupo no WhatsApp (opcional)" full><input type="url" name="groupLink" placeholder="https://chat.whatsapp.com/..." defaultValue={d.settings.groupLink}/></Field><Field label="Mensagem para quem faltou" full><textarea name="missingText" rows={3} maxLength={2000} required defaultValue={missingText}/></Field><p className="form-section full">Automação da chamada</p><label className="check-label full"><input name="autoSunday" type="checkbox" defaultChecked={(d.settings as any).autoSunday!==false}/><span>Criar o culto de domingo automaticamente toda semana</span></label><Field label="Nome do culto de domingo"><input name="sundayTitle" maxLength={120} defaultValue={(d.settings as any).sundayTitle||'Culto de Domingo'}/></Field><Field label="Horário do culto de domingo"><input name="sundayTime" type="time" defaultValue={(d.settings as any).sundayTime||'18:00'}/></Field><Field label="Criar domingos a partir de"><input name="autoStart" type="date" defaultValue={(d.settings as any).autoStart||''}/></Field><Field label="Arquivar após quantas semanas sem presença"><input name="inactivityWeeks" type="number" min={0} max={104} defaultValue={(d.settings as any).inactivityWeeks??8}/></Field><p className="form-note full">Se não houve culto em um domingo, exclua-o na tela de Cultos e presença e ele não volta. Frequentantes que faltarem a todos os cultos no período indicado, sem alteração no cadastro, são arquivados sozinhos (use 0 para desligar).</p><div className="full"><Button type="submit" disabled={busy}>{busy?'Salvando…':'Salvar configurações'}</Button></div></form></section><div><EquipeAcessos me={me} aviso={setToast}/><section className="panel settings-info"><MessageCircle size={24}/><h2>WhatsApp</h2><Pill tone="amber">Integração automática não conectada</Pill><p>Agendamentos ficam salvos. O envio é assistido e precisa de confirmação no WhatsApp. Grupos e listas de transmissão são enviados pelo próprio aplicativo.</p></section></div></div>}
 <footer className="app-footer"><span><BookOpen size={14}/>JCR Marília <i>·</i> Cuidar de pessoas. Fortalecer a comunidade.</span><span><ShieldCheck size={13}/>Seu espaço de cuidado e organização</span></footer>
 </main></div>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toast}<button onClick={()=>setToast('')} aria-label="Dispensar"><X size={15}/></button></div>}
 </div>
}
function Stat({label,value,icon:Icon,note,tone,onClick}:{label:string;value:string;icon:any;note:string;tone:string;onClick?:()=>void}){return <div className={'stat-card '+(onClick?'clickable':'')} onClick={onClick} role={onClick?'button':undefined} tabIndex={onClick?0:undefined} onKeyDown={e=>{if(onClick&&(e.key==='Enter'||e.key===' '))onClick()}}><div><span>{label}</span><i className={'stat-icon '+tone}><Icon size={20}/></i></div><b>{value}</b><small>{tone==='mint'?<span className="mini-dot"/>:null}{note}{onClick&&<ArrowRight size={13}/>}</small></div>}
function Month({value,onChange}:{value:string;onChange:(v:string)=>void}){return <label className="month-control"><CalendarDays size={15}/><input aria-label="Selecionar mês" type="month" value={value} onChange={e=>{if(e.target.value)onChange(e.target.value)}}/></label>}
function shiftMonth(month:string,n:number){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function Calendar({month,services,selected,onSelect}:{month:string;services:Service[];selected:string;onSelect:(v:string)=>void}){const first=new Date(month+'-01T12:00:00');const days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();return <div className="calendar-grid">{['D','S','T','Q','Q','S','S'].map((w,i)=><b key={'w'+i}>{w}</b>)}{Array.from({length:first.getDay()},(_,i)=><span key={'empty'+i}/>)}{Array.from({length:days},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0');const ss=services.filter(s=>s.date===date);return <button key={date} aria-label={fmtDate(date,{day:'numeric',month:'long'})+(ss.length?`, ${ss.length} cultos`:'')} className={(date===today()?'today ':'')+(selected===date?'selected':'')} onClick={()=>onSelect(date)}>{i+1}<span>{ss.map(s=><i key={s.id} className={s.status}/>)}</span></button>})}</div>}
function PresenceChart({data,month}:{data:Data;month:string}){const ss=data.services.filter(s=>s.date.startsWith(month)&&s.date<=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const values=ss.map(s=>presentesNoCulto(data,s));const max=Math.max(10,...values);const points=values.map((v,i)=>`${50+i*(650/Math.max(values.length-1,1))},${170-v/max*135}`).join(' ');return <div className="presence-chart"><svg viewBox="0 0 760 220" role="img" aria-label={ss.length?'Gráfico de presenças por culto':'Nenhum culto realizado neste mês'}><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#4b7ac1" stopOpacity=".28"/><stop offset="100%" stopColor="#4b7ac1" stopOpacity=".02"/></linearGradient></defs>{[0,1,2,3].map(i=><g key={i}><text x="2" y={40+i*44} fill="#7d8ca0" fontSize="11">{Math.round(max*(1-i/3))}</text><line x1="35" x2="736" y1={36+i*44} y2={36+i*44} stroke="#e6ebf3" strokeDasharray="3 5"/></g>)}{ss.length?<><polygon points={`50,170 ${points} ${50+(values.length-1)*(650/Math.max(values.length-1,1))},170`} fill="url(#chart-fill)"/><polyline points={points} fill="none" stroke="#3568b4" strokeWidth="3" strokeLinejoin="round"/>{values.map((v,i)=><g key={ss[i].id}><circle cx={50+i*(650/Math.max(values.length-1,1))} cy={170-v/max*135} r="4.5" fill="#3568b4" stroke="white" strokeWidth="2"/><text x={50+i*(650/Math.max(values.length-1,1))} y="201" textAnchor="middle" fill="#71839b" fontSize="11">{ss[i].date.slice(8)}/{month.slice(5)}</text></g>)}</>:<><text x="386" y="105" textAnchor="middle" fill="#6b7e98" fontSize="13">A história da sua comunidade vai aparecer aqui.</text><text x="386" y="128" textAnchor="middle" fill="#8191a8" fontSize="11">Os cultos realizados aparecem aqui.</text>{['01','07','14','21','28'].map((v,i)=><text key={v} x={50+i*162} y="201" textAnchor="middle" fill="#71839b" fontSize="11">{v}/{month.slice(5)}</text>)}</>}</svg></div>}
